head.b:skin:
:root {
    --bg-body: #050b14;
    --bg-surface: #0d1722;
    --accent-color: #00e5ff;
    --text-main: #cbd5e1;
    --text-muted: #94a3b8;
    --border-color: #1a2736;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html {
    scroll-behavior: smooth;
    background: var(--bg-body);
}

body {
    background: var(--bg-body);
    color: var(--text-main);
    font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
    line-height: 1.4;
    overflow-x: hidden;
}

a {
    color: inherit;
    text-decoration: none;
}

/* HEADER — Gaya Hiru404 */
#header-bar {
    width: 100%;
    min-height: 40px;
    padding: 6px 14px;
    background: var(--bg-surface);
    color: #fff;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    position: sticky;
    top: 0;
    z-index: 1000;
    border-bottom: 1px solid var(--border-color);
    box-shadow: 0 0 15px rgba(0,229,255,0.05);
}

#header-bar form {
    display: flex;
    align-items: center;
    gap: 8px;
    min-width: 0;
}

#header-bar label {
    font-size: 11px;
    white-space: nowrap;
    color: var(--text-muted);
    font-weight: 600;
}

#header-bar input[type="text"] {
    width: 220px;
    height: 28px;
    padding: 4px 10px;
    border: 1px solid var(--border-color);
    border-radius: 6px;
    background: var(--bg-body);
    color: #fff;
    font-size: 11px;
    outline: none;
}

#header-bar input[type="text"]:focus {
    border-color: var(--accent-color);
    box-shadow: 0 0 8px rgba(0,229,255,0.2);
}

#header-bar input[type="button"] {
    height: 28px;
    padding: 0 12px;
    border: 0;
    border-radius: 6px;
    background: var(--accent-color);
    color: var(--bg-body);
    font-size: 11px;
    font-weight: 800;
    cursor: pointer;
    transition: opacity 0.2s;
}

#header-bar input[type="button"]:hover {
    opacity: 0.9;
}

.about-links {
    display: flex;
    align-items: center;
    gap: 14px;
    flex-shrink: 0;
}

.about-links a {
    color: var(--text-main);
    font-size: 11px;
    font-weight: 600;
}

.about-links a:hover {
    color: var(--accent-color);
}

/* TOMBOL DEVICE */
.btn-toggle {
    position: fixed;
    top: 50px;
    right: 10px;
    bottom: auto;
    width: 36px;
    height: 36px;
    border-radius: 8px;
    display: flex;
    justify-content: center;
    align-items: center;
    background: var(--bg-surface);
    color: var(--accent-color);
    border: 1px solid var(--border-color);
    cursor: pointer;
    z-index: 1100;
    box-shadow: 0 0 10px rgba(0,229,255,0.1);
    font-size: 14px;
}

.btn-toggle:hover {
    background: var(--border-color);
}

.deviceState { display: none; }

.devicecont {
    position: fixed;
    inset: 0;
    background: rgba(5,11,20,.8);
    backdrop-filter: blur(4px);
    display: none;
    z-index: 1200;
}

.deviceState:checked ~ .devicecont {
    display: block;
}

.devBg {
    position: absolute;
    inset: 0;
}

.device-drawer {
    position: absolute;
    right: 0;
    top: 0;
    width: min(280px, 86vw);
    height: 100%;
    padding: 18px;
    overflow-y: auto;
    background: var(--bg-surface);
    color: var(--text-main);
    border-left: 1px solid var(--border-color);
    box-shadow: -5px 0 20px rgba(0,0,0,.5);
}

.device-drawer p {
    margin-bottom: 12px;
    padding-bottom: 9px;
    border-bottom: 1px solid var(--border-color);
    font-weight: 700;
    font-size: 14px;
    color: var(--accent-color);
}

.device-drawer ul {
    list-style: none;
}

.device-drawer ul li {
    margin-bottom: 7px;
}

.device-drawer ul li a {
    display: block;
    padding: 8px 10px;
    border-radius: 6px;
    background: var(--bg-body);
    color: var(--text-main);
    font-size: 12px;
    border: 1px solid var(--border-color);
    transition: all 0.2s;
}

.device-drawer ul li a:hover {
    background: var(--border-color);
    color: var(--accent-color);
    border-color: var(--accent-color);
}

/* PREVIEW CONTAINER */
.preview-container {
    width: 100%;
    max-width: none;
    margin: 42px 0 0;
    padding: 0 10px 45px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;
    gap: 36px;
}

.device-wrapper {
    width: auto;
    max-width: 100%;
    padding: 0;
    margin: 0;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    justify-content: flex-start;
    background: transparent;
    border-radius: 0;
    box-shadow: none;
}

.device-box {
    position: relative;
    width: 100%;
    margin: 0;
    padding: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 auto;
    background: #0d1722;
    border: 1px solid var(--border-color);
    border-radius: 12px;
    box-shadow: 0 0 20px rgba(0,0,0,.4);
}

.device-screen {
    position: relative;
    width: 100%;
    height: 100%;
    overflow: hidden;
    background: #fff;
    border-radius: 16px;
    isolation: isolate;
}

.device-screen iframe {
    display: block;
    width: 100%;
    height: 100%;
    border: 0;
    background: #fff;
}

/* indikator loading */
.device-screen::after {
    content: '';
    position: absolute;
    left: 50%;
    top: 50%;
    width: 12px;
    height: 4px;
    transform: translate(-50%, -50%);
    background:
        radial-gradient(circle, var(--accent-color) 0 1.5px, transparent 2px) 0 50%/4px 4px repeat-x;
    opacity: .9;
    pointer-events: none;
    z-index: 20;
}

.device-screen.loaded::after {
    display: none;
}

/* DEVICE SIZES */
.iphone-13-pro {
    width: 390px;
    max-width: 390px;
    height: 844px;
}

.poni-ip13 {
    position: absolute;
    top: 0;
    left: 50%;
    width: 150px;
    height: 30px;
    transform: translateX(-50%);
    pointer-events: none;
    z-index: 30;
}

.iphone-13-pro-h {
    width: 844px;
    max-width: 844px;
    height: 390px;
}

.poni-ip13-h {
    position: absolute;
    top: 50%;
    left: 0;
    width: 30px;
    height: 150px;
    transform: translateY(-50%);
    pointer-events: none;
    z-index: 30;
}

.renote10 {
    width: 393px;
    max-width: 393px;
    height: 873px;
}

.renote-top {
    position: absolute;
    top: 0;
    left: 50%;
    width: 120px;
    height: 25px;
    transform: translateX(-50%);
    pointer-events: none;
    z-index: 30;
}

.renote-bottom {
    position: absolute;
    bottom: 0;
    left: 50%;
    width: 120px;
    height: 15px;
    transform: translateX(-50%);
    pointer-events: none;
    z-index: 30;
}

.renote10h {
    width: 873px;
    max-width: 873px;
    height: 393px;
}

.renote-top-h {
    position: absolute;
    top: 50%;
    left: 0;
    width: 25px;
    height: 120px;
    transform: translateY(-50%);
    pointer-events: none;
    z-index: 30;
}

.android-old {
    width: 360px;
    max-width: 360px;
    height: 640px;
}

.android-old-top {
    position: absolute;
    top: 0;
    left: 50%;
    width: 140px;
    height: 20px;
    transform: translateX(-50%);
    pointer-events: none;
    z-index: 30;
    background: #222;
    border-bottom-left-radius: 8px;
    border-bottom-right-radius: 8px;
}

.android-old-h {
    width: 640px;
    max-width: 640px;
    height: 360px;
}

.android-old-top-h {
    position: absolute;
    top: 50%;
    left: 0;
    width: 20px;
    height: 140px;
    transform: translateY(-50%);
    pointer-events: none;
    z-index: 30;
    background: #222;
    border-top-right-radius: 8px;
    border-bottom-right-radius: 8px;
}

.iphone6 {
    width: 375px;
    max-width: 375px;
    height: 667px;
}

.iphone6-top {
    position: absolute;
    top: 0;
    left: 50%;
    width: 180px;
    height: 35px;
    transform: translateX(-50%);
    pointer-events: none;
    z-index: 30;
}

.iphone6-bottom {
    position: absolute;
    bottom: 0;
    left: 50%;
    width: 180px;
    height: 35px;
    transform: translateX(-50%);
    pointer-events: none;
    z-index: 30;
}

.iphone6h {
    width: 667px;
    max-width: 667px;
    height: 375px;
}

.iphone6-top-h {
    position: absolute;
    left: 0;
    top: 50%;
    width: 35px;
    height: 180px;
    transform: translateY(-50%);
    pointer-events: none;
    z-index: 30;
}

.fold {
    width: 280px;
    max-width: 280px;
    height: 700px;
}

.fold-top {
    position: absolute;
    top: 0;
    left: 50%;
    width: 100px;
    height: 20px;
    transform: translateX(-50%);
    pointer-events: none;
    z-index: 30;
}

.foldh {
    width: 653px;
    max-width: 653px;
    height: 340px;
}

.fold-top-h {
    position: absolute;
    top: 50%;
    left: 0;
    width: 20px;
    height: 100px;
    transform: translateY(-50%);
    pointer-events: none;
    z-index: 30;
}

.ipad {
    width: 768px;
    max-width: 768px;
    height: 1024px;
}

.ipadtop {
    position: absolute;
    top: 0;
    left: 50%;
    width: 200px;
    height: 25px;
    transform: translateX(-50%);
    pointer-events: none;
    z-index: 30;
}

.ipadh {
    width: 1024px;
    max-width: 1024px;
    height: 768px;
}

.ipadtop-h {
    position: absolute;
    top: 50%;
    left: 0;
    width: 25px;
    height: 200px;
    transform: translateY(-50%);
    pointer-events: none;
    z-index: 30;
}

.device-desc {
    width: 100%;
    margin-top: 8px;
    padding-left: 2px;
    color: var(--text-muted);
    font-size: 11px;
    line-height: 1.2;
    text-align: left;
    font-weight: 600;
}

footer {
    width: 100%;
    margin-top: 20px;
    padding: 20px;
    border-top: 1px solid var(--border-color);
    background: var(--bg-surface);
    color: var(--text-muted);
    text-align: center;
    font-size: 11px;
}

/* Responsif Layar Kecil */
@media (max-width: 600px) {
    #header-bar {
        padding: 6px 10px;
    }

    #header-bar label {
        display: none;
    }

    #header-bar input[type="text"] {
        width: min(55vw, 180px);
    }

    .about-links {
        gap: 10px;
    }

    .about-links a {
        font-size: 10px;
    }

    .preview-container {
        gap: 30px;
        margin-top: 36px;
    }

    .device-wrapper {
        width: 100%;
        max-width: 100%;
        overflow: visible;
    }

    .device-box {
        transform-origin: top left;
    }

    .device-box.iphone-13-pro,
    .device-box.renote10,
    .device-box.android-old,
    .device-box.iphone6,
    .device-box.fold {
        max-width: calc(100vw - 20px);
    }

    .iphone-13-pro,
    .renote10,
    .android-old,
    .iphone6,
    .fold {
        transform: scale(min(1, calc((100vw - 20px) / var(--device-width, 390))));
    }
}

@media (max-width: 420px) {
    .iphone-13-pro { --device-width: 390; }
    .renote10 { --device-width: 393; }
    .android-old { --device-width: 360; }
    .iphone6 { --device-width: 375; }
    .fold { --device-width: 280; }
}

/* ===== MODE GET (halaman awal tanpa ?url=) - tema cyber gelap ===== */
.get-page { display: none; }
html.mode-get #header-bar,
html.mode-get .btn-toggle,
html.mode-get .deviceState,
html.mode-get .devicecont,
html.mode-get .preview-container { display: none !important; }
html.mode-get footer { display: block !important; }
html.mode-get .get-page {
    display: block;
    padding: 60px 14px 40px;
    background-image:
        linear-gradient(rgba(0,229,255,.04) 1px, transparent 1px),
        linear-gradient(90deg, rgba(0,229,255,.04) 1px, transparent 1px);
    background-size: 32px 32px;
    min-height: 100vh;
}
.get-card {
    max-width: 600px;
    margin: 0 auto;
    background: var(--bg-surface);
    border: 1px solid var(--border-color);
    border-radius: 14px;
    padding: 36px 22px 26px;
    box-shadow: 0 0 0 1px rgba(0,229,255,.06), 0 0 28px rgba(0,229,255,.08);
    color: var(--text-main);
}
.get-card h1 {
    font-size: 22px;
    text-align: center;
    margin-bottom: 16px;
    color: #fff;
    letter-spacing: .5px;
}
.get-card h1::after {
    content: '';
    display: block;
    width: 56px;
    height: 2px;
    margin: 12px auto 0;
    background: var(--accent-color);
    box-shadow: 0 0 10px var(--accent-color);
}
.get-card .get-desc {
    text-align: center;
    font-size: 14px;
    color: var(--text-muted);
    margin-bottom: 24px;
}
.get-card form { text-align: center; }
.get-card input[type=text] {
    width: 100%;
    padding: 13px 14px;
    font-size: 15px;
    font-family: inherit;
    border: 1px solid var(--border-color);
    border-radius: 8px;
    background: var(--bg-body);
    color: var(--accent-color);
    margin-bottom: 16px;
    outline: none;
}
.get-card input[type=text]::placeholder { color: #475569; }
.get-card input[type=text]:focus {
    border-color: var(--accent-color);
    box-shadow: 0 0 0 3px rgba(0,229,255,.15);
}
.get-card button {
    background: var(--accent-color);
    color: var(--bg-body);
    border: 0;
    border-radius: 8px;
    padding: 13px 38px;
    font-size: 15px;
    font-weight: bold;
    font-family: inherit;
    letter-spacing: 1px;
    text-transform: uppercase;
    cursor: pointer;
    box-shadow: 0 0 16px rgba(0,229,255,.45);
}
.get-card button:active { transform: translateY(1px); box-shadow: 0 0 8px rgba(0,229,255,.6); }
.get-steps { margin-top: 24px; }
.get-step {
    background: var(--bg-body);
    border: 1px solid var(--border-color);
    border-left: 3px solid var(--accent-color);
    border-radius: 8px;
    padding: 11px 13px;
    margin-bottom: 8px;
    font-size: 13px;
    line-height: 1.5;
    color: var(--text-main);
}
.get-step b { color: var(--accent-color); }
.get-step code {
    font-family: inherit;
    color: var(--accent-color);
    background: rgba(0,229,255,.08);
    padding: 1px 5px;
    border-radius: 4px;
}
.get-warn {
    margin-top: 24px;
    background: rgba(255,59,92,.08);
    border: 1px solid rgba(255,59,92,.35);
    color: #ff6b85;
    border-radius: 8px;
    padding: 13px;
    text-align: center;
    font-size: 13px;
    line-height: 1.5;
}
.get-warn b { color: #ff9aae; }

body.script:
//
(function () {
  'use strict';
  var hasGet = false;
  try {
    var params = new URLSearchParams(window.location.search);
    var value = params.get('get');
    hasGet = !!(value && value.trim());
  } catch (e) {
    hasGet = /(?:^|&)get=[^&]+/i.test(window.location.search.replace(/^\?/, ''));
  }
  document.documentElement.classList.add(hasGet ? 'mode-preview' : 'mode-get');
})();
//
